export default function GeoJsonToSvg() {
    const width = 600;
    const height = 400;
    const padding = 24;

    // Fix the winding order of your GeoJSON features
    const correctedGeojson = rewind(geojsonData, { mutate: true, reverse: true });


    const projection = geoIdentity()
        .reflectY(true)
        .fitExtent([[padding, padding], [width - padding, height - padding]], correctedGeojson);

    const pathGenerator = geoPath().projection(projection);

    // return (
    //     <svg width={width} height={height} style={{ border: "1px solid #ccc" }}>
    //         {geojsonData.features.map((feature: any, index: number) => (
    //             <path
    //                 key={index}
    //                 d={pathGenerator(feature) || ""}
    //                 fill="#3388ff"
    //                 stroke="#000"
    //                 strokeWidth={1}
    //             />
    //         ))}
    //     </svg>
    // );

    return (
        <div className="rounded-xl border bg-card text-card-foreground shadow">
            {/* Header wrapper replicating standard shadcn CardHeader component */}
            <div className="flex justify-between">
                <div className="flex flex-col space-y-1.5 p-6 pb-4">
                    <h3 className="font-semibold tracking-tight text-lg">Floor Plan</h3>
                    <p className="text-sm text-muted-foreground">Spatial boundary configuration preview.</p>
                </div>
                <div className="p-6">
                    <svg width="200" height="150" className="bg-white p-4 rounded shadow">

                        {/* First Legend Item - Red */}
                        <g transform="translate(20, 30)">
                            <circle
                                cx="0"
                                cy="0"
                                r="6"
                                className="fill-red-500 stroke-white stroke-2"
                            />
                            <text x="20" y="5" className="text-sm font-medium fill-gray-700">
                                Restrooms
                            </text>
                        </g>

                        {/* Second Legend Item - Blue */}
                        <g transform="translate(20, 60)">
                            <circle
                                cx="0"
                                cy="0"
                                r="6"
                                className="fill-blue-500 stroke-white stroke-2"
                            />
                            <text x="20" y="5" className="text-sm font-medium fill-gray-700">
                                Stairs
                            </text>
                        </g>

                        {/* Third Legend Item - Green */}
                        <g transform="translate(20, 90)">
                            <circle
                                cx="0"
                                cy="0"
                                r="6"
                                className="fill-green-500 stroke-white stroke-2"
                            />
                            <text x="20" y="5" className="text-sm font-medium fill-gray-700">
                                Spaces
                            </text>
                        </g>

                    </svg>
                </div>
            </div>
            {/* SVG Container utilizing CSS variable colors for system compatibility (Light/Dark mode) */}
            <div className="p-6 pt-0 flex justify-center">
                <div className="relative w-full overflow-hidden rounded-md border bg-muted/20 p-2">
                    <svg
                        viewBox={`0 0 ${width} ${height}`}
                        className="w-full h-auto max-h-[400px] drop-shadow-sm"
                    >
                        {geojsonData.features.map((feature: Feature) => {
                            const category = feature.properties?.category || 'unknown'
                            const isBookable = (category === 'desk' || category === 'conferenceroom')
                            const hasIcon = (category === 'restroom' || category === 'stairs')

                            // 1. Declare variables outside the block so they are scoped to the whole function
                            let centroid: [number, number] | null = null;
                            let hasCenter = false;
                            if (isBookable || hasIcon) {

                                // Calculate the center [x, y] coordinates of the feature
                                centroid = pathGenerator.centroid(feature);
                                hasCenter = !!(centroid && !isNaN(centroid[0]) && !isNaN(centroid[1]));

                                if (hasIcon) {
                                    console.log(feature)
                                    console.log(centroid)
                                    console.log(hasCenter)
                                }
                            }
                            return <Fragment key={feature.id}>
                                <path
                                    d={pathGenerator(feature) || ""}
                                    className="fill-primary/10 stroke-primary stroke-2 transition-colors duration-200 hover:fill-primary/20 cursor-pointer"
                                />
                                {hasIcon && hasCenter && centroid && category == 'restroom' && (
                                    <circle
                                        cx={centroid[0]}
                                        cy={centroid[1]}
                                        r="6"
                                        className="fill-red-500 stroke-white stroke-2 pointer-events-none"
                                    />
                                    // <svg x={centroid[0]}
                                    //     y={centroid[1]} xmlns="http://www.w3.org/2000/svg" fill="none" stroke="currentColor" strokeWidth="2" stroke-linecap="round" stroke-linejoin="round" className="lucide lucide-toilet-icon lucide-toilet"><path d="M7 12h13a1 1 0 0 1 1 1 5 5 0 0 1-5 5h-.598a.5.5 0 0 0-.424.765l1.544 2.47a.5.5 0 0 1-.424.765H5.402a.5.5 0 0 1-.424-.765L7 18" /><path d="M8 18a5 5 0 0 1-5-5V4a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v8" /></svg>
                                )}
                                {hasIcon && hasCenter && centroid && category == 'stairs' && (
                                    <circle
                                        cx={centroid[0]}
                                        cy={centroid[1]}
                                        r="6"
                                        className="fill-blue-500 stroke-white stroke-2 pointer-events-none"
                                    />
                                    // <svg x={centroid[0]}
                                    //     y={centroid[1]} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" stroke-linecap="round" stroke-linejoin="round" className="lucide lucide-stairs-icon lucide-stairs"><rect width="10" height="4" x="2" y="16" /><rect width="10" height="4" x="4" y="12" /><rect width="10" height="4" x="6" y="8" /><rect width="10" height="4" x="8" y="4" /><path d="M12 20h10V4h-4" /></svg>
                                )}
                                {isBookable && hasCenter && centroid && (
                                    /* Centered Circle (only renders if valid center exists) */
                                    <circle
                                        cx={centroid[0]}
                                        cy={centroid[1]}
                                        r="6"
                                        className="fill-green-500 stroke-white stroke-2 pointer-events-none"
                                    />
                                )}
                            </Fragment>
                        })}
                    </svg>
                </div>
            </div>
        </div>
    );
}
